// Stops the website server leaking memory on every request.
//
// The site runs as the Cloud Function `ssrkrishidukane8315`, whose wrapper is
// generated by Firebase (`firebase-frameworks`). For EVERY request it does:
//
//     await nextApp.prepare();
//     await nextApp.getRequestHandler()(req, res);
//
// In Next 14 (checked up to 14.2.35), a custom server's prepare() is not
// memoized: each call rebuilds Next's router layer (re-reads config and route
// manifests) and adds two process.on('uncaughtException' / 'unhandledRejection')
// listeners that are never removed. Those listeners keep every rebuilt router
// alive, so memory grows ~0.6 MB per request. Measured against the production
// build: 80 MB at start, 292 MB after 300 requests (vs flat 88 MB with this
// patch). At the old 256 MiB limit an instance was killed every ~250 requests,
// taking down whatever was in flight - including payment checkouts
// ("Failed to create order: Internal Server Error", 12 Nov 2026).
//
// next.config.js is loaded during that first prepare(), so this patches the
// shared NextCustomServer prototype: once an instance has its request handler,
// further prepare() calls return immediately; concurrent first calls share one
// initialisation. Only applied inside the deployed function (K_SERVICE /
// FUNCTION_TARGET are set by Cloud Run / Cloud Functions), never at build time
// or in `next dev`.
//
// Remove when either firebase-frameworks stops calling prepare() per request or
// Next memoizes it - check node_modules/firebase-frameworks/dist/next.js/index.js
// and NextCustomServer.prepare in node_modules/next/dist/server/next.js.

const FLAG = Symbol.for("krishidukan.nextPrepareOnce");

function applyNextPrepareOnce({ force = false } = {}) {
  const inFunction = !!(process.env.K_SERVICE || process.env.FUNCTION_TARGET);
  if (!force && !inFunction) return false;
  if (globalThis[FLAG]) return true;

  try {
    // Plain require of the installed package (kept external by Firebase's
    // config bundler, as `next` is a dependency).
    const createServer = require("next");
    // A throwaway instance only to reach the prototype; the constructor just
    // stores its options.
    const probe = createServer({ dev: false, dir: process.cwd() });
    const proto = Object.getPrototypeOf(probe);
    const original = proto && proto.prepare;
    if (typeof original !== "function") {
      console.warn("[next-prepare-once] prepare() not found; not applied");
      return false;
    }

    const pending = new WeakMap();
    proto.prepare = function prepareOnce() {
      // Already initialised: the first prepare() set this, and reusing it is
      // exactly what Next's own standalone server does.
      if (this.requestHandler) return Promise.resolve();
      let p = pending.get(this);
      if (!p) {
        p = original.call(this).catch((err) => {
          // Let the next request retry a failed initialisation.
          pending.delete(this);
          throw err;
        });
        pending.set(this, p);
      }
      return p;
    };

    globalThis[FLAG] = true;
    console.log("[next-prepare-once] applied");
    return true;
  } catch (err) {
    console.warn("[next-prepare-once] not applied:", err);
    return false;
  }
}

module.exports = { applyNextPrepareOnce };
